def transform(grid):
    """Fill one-cell horizontal gaps between matching foreground markers with 2."""
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    output = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != background and row[c + 1] == background and row[c + 2] == row[c]:
                output[r][c + 1] = 2
    return output
